import{_ as n,a0 as o,w as d,s as r,ao as p,I as a,x as t,a1 as s,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"使用 Ultimate Plumber 即時預覽管道命令結果 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Ultimate Plumber 即時預覽管道命令結果 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Ultimate Plumber 即時預覽管道命令結果 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Ultimate Plumber 即時預覽管道命令結果 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181026 Ultimate Plumber - Writing Linux Pipes With Instant Live Preview","title":"使用 Ultimate Plumber 即時預覽管道命令結果","tag":"201811","desc":""},"relativePath":"201811/20181026 Ultimate Plumber - Writing Linux Pipes With Instant Live Preview.md","filePath":"[post].md"}'),u={name:"201811/20181026 Ultimate Plumber - Writing Linux Pipes With Instant Live Preview.md"};function m(h,e,c,b,g,k){const i=o("Link");return d(),r("div",null,[e[20]||(e[20]=p(`<h1 id="使用-ultimate-plumber-即時預覽管道命令結果" tabindex="-1">使用 Ultimate Plumber 即時預覽管道命令結果 <a class="header-anchor" href="#使用-ultimate-plumber-即時預覽管道命令結果" aria-label="Permalink to “使用 Ultimate Plumber 即時預覽管道命令結果”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/Ultimate-Plumber-720x340.jpg" alt=""></p><p>管道命令的作用是將一個命令/程序/進程的輸出發送給另一個命令/程序/進程，以便將輸出結果進行進一步的處理。我們可以通過使用管道命令把多個命令組合起來，使一個命令的標準輸入或輸出重定向到另一個命令。兩個或多個 Linux 命令之間的豎線字符（<code>|</code>）表示在命令之間使用管道命令。管道命令的一般語法如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Command-1 | Command-2 | Command-3 | …| Command-N</span></span></code></pre></div><p>Ultimate Plumber（簡稱 UP）是一個命令列工具，它可以用於即時預覽管道命令結果。如果你在使用 Linux 時經常會用到管道命令，就可以通過它更好地運用管道命令了。它可以預先顯示執行管道命令後的結果，而且是即時滾動地顯示，讓你可以輕鬆構建複雜的管道。</p><p>下文將會介紹如何安裝 UP 並用它將複雜管道命令的編寫變得簡單。</p><p><strong>重要警告：</strong></p><p>在生產環境中請謹慎使用 UP！在使用它的過程中，有可能會在無意中刪除重要數據，尤其是搭配 <code>rm</code> 或 <code>dd</code> 命令時需要更加小心。勿謂言之不預。</p><h3 id="使用-ultimate-plumber-即時預覽管道命令" tabindex="-1">使用 Ultimate Plumber 即時預覽管道命令 <a class="header-anchor" href="#使用-ultimate-plumber-即時預覽管道命令" aria-label="Permalink to “使用 Ultimate Plumber 即時預覽管道命令”">​</a></h3><p>下面給出一個簡單的例子介紹 <code>up</code> 的使用方法。如果需要將 <code>lshw</code> 命令的輸出傳遞給 <code>up</code>，只需要在終端中輸入以下命令，然後回車：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lshw |&amp; up</span></span></code></pre></div><p>你會在屏幕頂部看到一個輸入框，如下圖所示。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/Ultimate-Plumber.png" alt=""></p><p>在輸入命令的過程中，輸入管道符號並回車，就可以立即執行已經輸入了的命令。Ultimate Plumber 會在下方的可滾動窗口中即時顯示管道命令的輸出。在這種狀態下，你可以通過 <code>PgUp</code>/<code>PgDn</code> 鍵或 <code>ctrl + ←</code>/<code>ctrl + →</code> 組合鍵來查看結果。</p><p>當你滿意執行結果之後，可以使用 <code>ctrl + x</code> 組合鍵退出 <code>UP</code>。而退出前編寫的管道命令則會保存在當前工作目錄的文件中，並命名為 <code>up1.sh</code>。如果這個文件名已經被佔用，就會命名為 <code>up2.sh</code>、<code>up3.sh</code> 等等以此類推，直到第 1000 個文件。如果你不需要將管道命令保存輸出，只需要使用 <code>ctrl + c</code> 組合鍵退出即可。</p><p>通過 <code>cat</code> 命令可以查看 <code>upX.sh</code> 文件的內容。例如以下是我的 <code>up2.sh</code> 文件的輸出內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat up2.sh</span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>grep network -A5 | grep : | cut -d: -f2- | paste - -</span></span></code></pre></div><p>如果通過管道發送到 <code>up</code> 的命令運行時間太長，終端窗口的左上角會顯示一個波浪號（~）字符，這就表示 <code>up</code> 在等待前一個命令的輸出結果作為輸入。在這種情況下，你可能需要使用 <code>ctrl + s</code> 組合鍵暫時凍結 <code>up</code> 的輸入緩衝區大小。在需要解凍的時候，使用 <code>ctrl + q</code> 組合鍵即可。Ultimate Plumber 的輸入緩衝區大小一般為 40 MB，到達這個限制之後，屏幕的左上角會顯示一個加號。</p><p>以下是 <code>up</code> 命令的一個簡單演示：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/up.gif" alt=""></p><h3 id="安裝-ultimate-plumber" tabindex="-1">安裝 Ultimate Plumber <a class="header-anchor" href="#安裝-ultimate-plumber" aria-label="Permalink to “安裝 Ultimate Plumber”">​</a></h3><p>喜歡這個工具的話，你可以在你的 Linux 系統上安裝使用。安裝過程也相當簡單，只需要在終端裏執行以下兩個命令就可以安裝 <code>up</code> 了。</p>`,22)),a("p",null,[e[1]||(e[1]=t("首先從 Ultimate Plumber 的",-1)),s(i,{href:"https://github.com/akavel/up/releases"},{default:l(()=>[...e[0]||(e[0]=[t("發佈頁面",-1)])]),_:1}),e[2]||(e[2]=t("下載最新的二進制文件，並將放在你係統的某個路徑下，例如 ",-1)),e[3]||(e[3]=a("code",null,"/usr/local/bin/",-1)),e[4]||(e[4]=t("。",-1))]),e[21]||(e[21]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo wget -O /usr/local/bin/up wget https://github.com/akavel/up/releases/download/v0.2.1/up</span></span></code></pre></div><p>然後向 <code>up</code> 二進制文件賦予可執行權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod a+x /usr/local/bin/up</span></span></code></pre></div><p>至此，你已經完成了 <code>up</code> 的安裝，可以開始編寫你的管道命令了。</p><hr>',5)),a("p",null,[e[6]||(e[6]=t("via: ",-1)),s(i,{href:"https://www.ostechnix.com/ultimate-plumber-writing-linux-pipes-with-instant-live-preview/"},{default:l(()=>[...e[5]||(e[5]=[t("https://www.ostechnix.com/ultimate-plumber-writing-linux-pipes-with-instant-live-preview/",-1)])]),_:1})]),a("p",null,[e[11]||(e[11]=t("作者：",-1)),s(i,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...e[7]||(e[7]=[t("SK",-1)])]),_:1}),e[12]||(e[12]=t(" 選題：",-1)),s(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[8]||(e[8]=[t("lujun9972",-1)])]),_:1}),e[13]||(e[13]=t(" 譯者：",-1)),s(i,{href:"https://github.com/HankChow"},{default:l(()=>[...e[9]||(e[9]=[t("HankChow",-1)])]),_:1}),e[14]||(e[14]=t(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:l(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[17]||(e[17]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[15]||(e[15]=[t("LCTT",-1)])]),_:1}),e[18]||(e[18]=t(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:l(()=>[...e[16]||(e[16]=[t("Linux中國",-1)])]),_:1}),e[19]||(e[19]=t(" 榮譽推出",-1))])])}const x=n(u,[["render",m]]);export{w as __pageData,x as default};
